import{_ as a,o as r,c as n,an as p}from"./chunks/framework.CwaL5rOX.js";const u=JSON.parse('{"title":"Examples","description":"","frontmatter":{},"headers":[],"relativePath":"examples/index.md","filePath":"examples/index.md","lastUpdated":null}'),t={name:"examples/index.md"};function l(s,e,i,o,d,c){return r(),n("div",null,[...e[0]||(e[0]=[p('<h1 id="Examples" tabindex="-1">Examples <a class="header-anchor" href="#Examples" aria-label="Permalink to &quot;Examples {#Examples}&quot;">​</a></h1><p>These pages document the package&#39;s example maneuvers. Each example builds an environment, plans a parking (or leaving) maneuver with <a href="/Parking.jl/previews/PR8/api#Parking.plan_park"><code>plan_park</code></a> / <a href="/Parking.jl/previews/PR8/api#Parking.plan_leave"><code>plan_leave</code></a>, and shows the resulting animation. The full, runnable source is shown inline on each page.</p><p>The examples are:</p><ul><li><p><strong><a href="./three_rows_parking">Three-row parking lot</a></strong> - generated 3×5 lot with a single free center spot; plan a perpendicular park-in through the lot.</p></li><li><p><strong><a href="./perpendicular_parking">Perpendicular parking</a></strong> - nose-in parking into a spot flanked by parked cars and a back wall.</p></li><li><p><strong><a href="./perpendicular_nose_out">Perpendicular nose-out</a></strong> - reverse-in / nose-out parking into the same constrained spot.</p></li><li><p><strong><a href="./parallel_parking">Parallel parking</a></strong> - parallel parking on a tight street, plus the reverse &quot;pull out&quot; problem.</p></li></ul><p>The planned trajectories shown in this documentation are stored under <code>docs/src/figures/</code>.</p>',5)])])}const g=a(t,[["render",l]]);export{u as __pageData,g as default};
